-- public.foundation_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.foundation_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare tx int; ty int; f foundation; v_tool text;
begin
  if p_target->>'kind' is distinct from 'tile' then return 'Point at a tile.'; end if;
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  f := foundation_at(p_world, tx, ty);
  -- A pool dug in a poured slab (`dig_pool`, `fill_pool` in src/game/foundations.ts).
  if p_action = 'dig_pool' then
    if need_tool(p_world, p_uid, 'pickaxe') is not null then return 'Need a pickaxe.'; end if;
    if pack_count(p_world, p_uid, water_mote()) < water_motes_each() then return water_mote_need(); end if;
    return pool_reason(p_world, tx, ty);
  end if;
  if p_action = 'fill_pool' then
    if not coalesce((slab_at(p_world, tx, ty)).pool, false) then return 'No pool here.'; end if;
    if need_tool(p_world, p_uid, 'trowel') is not null then return 'Need a trowel.'; end if;
    if pack_count(p_world, p_uid, 'concrete') < pool_fill() then
      return 'Need ' || pool_fill() || ' concrete; have ' || pack_count(p_world, p_uid, 'concrete') || '.';
    end if;
    return null;
  end if;
  if p_action = 'plan_foundation' then
    v_tool := need_tool(p_world, p_uid, 'mallet');
    if v_tool is not null then return v_tool; end if;
    if tile_slope(p_world, tx, ty) = 0 then
      return 'Tile already level.';
    end if;
    return foundation_reason(p_world, p_uid, tx, ty, foundation_top(p_world, p_uid, tx, ty));
  end if;
  if f.id is null then return 'No shuttering here.'; end if;
  if p_action = 'strike_foundation' then
    if bill_done(f.needed) then return 'Already poured: not a plan.'; end if;
    return null;
  end if;
  -- Pouring.
  if bill_done(f.needed) then return 'Already poured.'; end if;
  v_tool := need_tool(p_world, p_uid, 'trowel');
  if v_tool is not null then return 'Need a trowel.'; end if;
  if pack_count(p_world, p_uid, 'concrete') < 1 then return 'Need concrete.'; end if;
  return null;
end $function$
